import pandas as pdruta = "datos/"cols = ["fuente", "texto", "tipo", "id_post", "fecha", "calificacion", "clase"]# Instagramig = pd.read_csv(ruta + "instaUGC.csv")ig = pd.DataFrame({"fuente": "instagram", "texto": ig["description"]})# SECTURsec = pd.read_csv(ruta + "sectur.csv")sec = pd.DataFrame({"fuente": "sectur", "texto": sec["texto"], "clase": sec["clase"]})# TripAdvisorta = pd.read_csv(ruta + "TripAdvisor.csv")ta = pd.DataFrame({    "fuente": "tripadvisor",    "texto": ta["texto"],    "fecha": pd.to_datetime(ta["date"], format="%d/%m/%Y", errors="coerce"),    "calificacion": pd.to_numeric(ta["target"], errors="coerce"),})# Reddit: una fila por publicación y una por comentariord = pd.read_csv(ruta + "redditcdmx.csv")rd["id_post"] = range(len(rd))post = pd.DataFrame({    "fuente": "reddit",    "texto": rd["title"] + ". " + rd["text"].fillna(""),    "id_post": rd["id_post"],    "tipo": "post",})com = rd[["id_post", "comments"]].dropna()com["texto"] = com["comments"].str.split(" - ")com = com.explode("texto")com["texto"] = com["texto"].str.strip()com["fuente"] = "reddit"com["tipo"] = "comentario"bot = com["texto"].str.contains("I am a bot", case=False)borr = com["texto"].str.lower().isin(["deleted", "removed"])com = com[~bot & ~borr]# Unificardf = pd.concat([ig, sec, ta, post, com], ignore_index=True)[cols]df.to_csv(ruta + "base_unificada.csv", index=False)print(df["fuente"].value_counts())print(f"Quitados en Reddit: {bot.sum()} del bot, {borr.sum()} borrados")